sa.productCount, sa.aCount, sa.bCount, sa.cCount, sa.dCount, sa.unknownCount, (sa.aCount + sa.bCount) AS abCount, (sa.aCount + sa.bCount + sa.cCount) AS abcCount, tc.topACategory, tc.topABCCategory, tc.topDCategory, sa.latestBatchDate FROM seller_agg sa LEFT JOIN top_categories tc ON tc.marketplace = sa.marketplace AND tc.sellerName = sa.sellerName
