SELECT id, marketplace, seller_name AS sellerName, seller_id AS sellerId, asin, parent_asin AS parentAsin,
    sales_tier_calc AS salesTier, title, brand, image_url AS imageUrl, product_url AS productUrl, similar_url AS similarUrl,
    node_id AS nodeId, node_label_path AS nodeLabelPath, category_leaf AS categoryLeaf, bsr_id AS bsrId,
    units, bsr, price, rating, ratings, fulfillment, available_date AS availableDate, batch_date AS batchDate, created_at AS createdAt
FROM base

    sales_tier_calc = #{salesTier}
    AND category_leaf = #{category}

ORDER BY
    CASE sales_tier_calc WHEN 'A' THEN 1 WHEN 'B' THEN 2 WHEN 'C' THEN 3 WHEN 'D' THEN 4 ELSE 5 END ASC,
    CASE WHEN units IS NULL THEN 1 ELSE 0 END ASC, units DESC,
    CASE WHEN bsr IS NULL OR bsr <= 0 THEN 1 ELSE 0 END ASC, bsr ASC, asin ASC
LIMIT #{offset}, #{size}


    WHERE ds.title IS NOT NULL AND ds.asin IS NOT NULL
      AND ds.marketplace = #{marketplace} AND ds.seller_name = #{sellerName}
    AND ds.batch_date = #{batchDate}
), base AS (SELECT * FROM ranked WHERE rn = 1)
SELECT marketplace, seller_name AS sellerName, sales_tier_calc AS salesTier, category_leaf AS categoryKey,
    COUNT(*) AS productCount, COALESCE(SUM(units), 0) AS unitsSum, ROUND(AVG(units), 2) AS unitsAvg
FROM base

    sales_tier_calc = #{salesTier}

GROUP BY marketplace, seller_name, sales_tier_calc, category_leaf
ORDER BY
    CASE sales_tier_calc WHEN 'A' THEN 1 WHEN 'B' THEN 2 WHEN 'C' THEN 3 WHEN 'D' THEN 4 ELSE 5 END ASC,
    productCount DESC, category_leaf ASC

mapper.sql:
CASE WHEN
    price BETWEEN #{priceMin} AND #{priceMax}
    AND weight_g IS NOT NULL
    AND weight_g < #{weightMax}
    AND listing_days IS NOT NULL
    AND listing_days < #{listingDaysMax}
    AND (
        (listing_days <= 30 AND units IS NOT NULL AND units >= #{sales30})
        OR (listing_days <= 60 AND units IS NOT NULL AND units >= #{sales60})
        OR (listing_days <= 90 AND units IS NOT NULL AND units >= #{sales90})

            OR (bsr IS NOT NULL AND bsr > 0 AND bsr < #{bsrMax})

    )
THEN 1 ELSE 0 END

