Count, SUM(CASE WHEN listing_days IS NOT NULL AND listing_days > 365 AND sales_tier_calc = 'D' THEN 1 ELSE 0 END) AS oldDCount, MAX(batch_date) AS latestBatchDate FROM enriched GROUP BY marketplace, seller_name ), category_source AS ( SELECT marketplace, seller_name AS sellerName, 'A' AS bucket, category_leaf FROM enriched WHERE sales_tier_calc = 'A' UNION ALL SELECT marketplace, seller_name AS sellerName, 'ABC' AS bucket, category_leaf FROM enriched WHERE sales_tier_calc IN ('A','B','C') UNION ALL SELECT marketplace, seller_name AS sellerName, 'D' AS bucket, category_leaf FROM enriched WHERE sales_tier_calc = 'D' ), category_counts AS ( SELECT marketplace, sellerName, bucket, category_leaf, COUNT(*) AS cnt FROM category_source GROUP BY marketplace, sellerName, bucket, category_leaf ), category_ranked AS ( SELECT category_counts.*, ROW_NUMBER() OVER ( PARTITION BY marketplace, sellerName, bucket ORDER BY cnt DESC, category_leaf ASC ) AS category_rank FROM category_counts ), top_categories AS ( SELECT marketplace, sellerName, MAX(CASE WHEN bucket = 'A' AND category_rank = 1 THEN category_leaf END) AS topACategory, MAX(CASE WHEN bucket = 'ABC' AND category_rank = 1 THEN category_leaf END) AS topABCCategory, MAX(CASE WHEN bucket = 'D' AND category_rank = 1 THEN category_leaf END) AS topDCategory FROM category_ranked GROUP BY marketplace, sellerName ) SELECT sa.marketplace, sa.sellerName, sa.sellerId, sa.productCount, sa.aCount, sa.bCount, sa.cCount, sa.dCount, sa.unknownCount, (sa.aCount + sa.bCount) AS abCount, (sa.aCount + sa.bCount + sa.cCount) AS abcCount, tc.topACategory, tc.topABCCategory, tc.topDCategory, sa.latestBatchDate, sa.m01HitCount, sa.m01HitRatio, sa.avgListingDays, sa.avgUnits, sa.earliestAvailableDate, sa.earliestAvailableDateText, sa.maxListingDays, sa.new30Count, sa.new90Count, sa.new180Count, sa.old180Count, sa.unknownListingDaysCount, sa.newProductCount, sa.newABCCount, ROUND(sa.newABCCount / NULLIF(sa.productCount, 0), 4) AS newABCRatio, sa.oldDCount, ROUND(sa.oldDCount / NULLIF(sa.productCount, 0), 4) AS oldDRatio FROM seller_agg sa LEFT JOIN top_categories tc ON tc.marketplace = sa.marketplace AND tc.sellerName = sa.sellerName
